# GENERATED by automation/render.py (network/wan.yml, kubernetes/cluster.yml) — kernel devices for wan1
# FRR's config refers to these, but zebra can't create them.  Idempotent: runs at container start
# (static/frr/start.sh) and before every `make apply` (roles/frr_router).
set -eu
# containerlab plugs the links after the container starts: wait for all of them
until [ "$(ls /sys/class/net | grep -c '^eth[1-9]')" -ge "${CLAB_INTFS:-0}" ]; do sleep 1; done
ip link show PROD >/dev/null 2>&1 || ip link add PROD type vrf table 100
ip link set PROD up
ip link show eth1.100 >/dev/null 2>&1 || ip link add link eth1 name eth1.100 type vlan id 100
ip link show eth2.100 >/dev/null 2>&1 || ip link add link eth2 name eth2.100 type vlan id 100
ip link show eth3.100 >/dev/null 2>&1 || ip link add link eth3 name eth3.100 type vlan id 100
ip link show eth4.100 >/dev/null 2>&1 || ip link add link eth4 name eth4.100 type vlan id 100
ip link show eth5.100 >/dev/null 2>&1 || ip link add link eth5 name eth5.100 type vlan id 100
ip link set eth6 master PROD up
ip link set eth7 master PROD up
ip link set eth1.100 master PROD up
ip link set eth2.100 master PROD up
ip link set eth3.100 master PROD up
ip link set eth4.100 master PROD up
ip link set eth5.100 master PROD up
